mapper.select:
SELECT

FROM SnsPost a WHERE 1 = 1

    AND a.userId LIKE CONCAT('%',#{userId}, '%')


    AND a.postTextContent LIKE CONCAT('%',#{postTextContent}, '%')


    AND a.postImageUrl LIKE CONCAT('%',#{postImageUrl}, '%')


    AND a.postVideoUrl LIKE CONCAT('%',#{postVideoUrl}, '%')


    AND a.openness = #{openness}


    AND a.viewer = #{viewer}


    AND a.lng LIKE CONCAT('%',#{lng}, '%')


    AND a.lat LIKE CONCAT('%',#{lat}, '%')


    AND a.city LIKE CONCAT('%',#{city}, '%')


    AND a.viewNum = #{viewNum}


    AND a.favoriteNum = #{favoriteNum}


    AND a.likeNum = #{likeNum}


    AND a.commentNum = #{commentNum}


    AND a.shareNum = #{shareNum}


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateTime = #{updateTime}

order by a.createTime desc

select ifnull(sum(case when openness = 1 then 1 else 0 end), 0) as totalPublicPostNum, count(*) as totalAllPostNum
from SnsPost
where userId = ${userId}
